// Combine both stores' reviews into one weekly HTML digest.
// HTML is assembled via the tag() helper so the workflow JSON stays free of
// literal markup (some proxies reject payloads that look like embedded HTML).
const LT = String.fromCharCode(60);
const GT = String.fromCharCode(62);
const tag = (t, attrs, inner) => LT + t + (attrs ? ' ' + attrs : '') + GT + (inner || '') + LT + '/' + t + GT;

// Each store is read from its own node, so a store that failed, or answered with
// nothing, is reported as unavailable instead of looking like a quiet week.
const STORES = [
  { name: 'App Store', node: 'Fetch App Store Reviews', text: (r) => [r.title, r.body] },
  { name: 'Google Play', node: 'Fetch Google Play Reviews', text: (r) => [r.text] },
];
const rowsOf = (node) => { try { return $(node).all().map((i) => i.json); } catch (e) { return []; } };
const reasonOf = (rows) => {
  const e = rows.find((r) => r.error);
  if (!e) return 'the store returned no data';
  if (e.errorType === 'NO_REVIEWS') return 'the store returned no reviews (a brand-new app, or the review feed came back empty)';
  const msg = typeof e.error === 'string' ? e.error : (e.error && e.error.message) || 'request failed';
  return 'the request failed: ' + msg;
};

const weekAgo = Date.now() - 7 * 24 * 3600 * 1000;
const esc = (s) => String(s).split('&').join('&amp;').split(LT).join('&lt;').split(GT).join('&gt;');
const trunc = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const stars = (n) => '★'.repeat(Math.round(n)) + '☆'.repeat(5 - Math.round(n));

let sections = '';
const recentAll = [];
const unavailable = [];
for (const store of STORES) {
  const rows = rowsOf(store.node);
  const reviews = rows.filter((r) => Number(r.rating) > 0).map((r) => ({
    rating: Number(r.rating),
    text: store.text(r).filter(Boolean).join(' — ').trim(),
    author: r.author || 'Anonymous',
    date: r.updated || r.date || null,
    version: r.version || '',
  }));
  sections += tag('h3', 'style="margin:18px 0 4px"', store.name);
  if (!reviews.length) {
    unavailable.push(store.name);
    sections += tag('p', 'style="color:#b45309"', 'Unavailable this week: ' + esc(reasonOf(rows)) + '. This is not counted as a quiet week.');
    continue;
  }
  const list = reviews.filter((r) => r.date && new Date(r.date).getTime() >= weekAgo);
  recentAll.push(...list);
  if (!list.length) {
    sections += tag('p', 'style="color:#666"', '0 new reviews this week.');
    continue;
  }
  const avg = list.reduce((a, r) => a + r.rating, 0) / list.length;
  const bad = list.filter((r) => r.rating <= 2).sort((a, b) => new Date(b.date) - new Date(a.date)).slice(0, 3);
  const plural = list.length === 1 ? '' : 's';
  sections += tag('p', '', tag('b', '', String(list.length)) + ' new review' + plural + ' · average ' + tag('b', '', avg.toFixed(2) + '★') + ' · ' + bad.length + ' negative');
  if (bad.length) {
    sections += tag('p', 'style="margin:8px 0 2px"', tag('b', '', 'Needs attention:'));
    for (const r of bad) {
      const meta = esc(r.author) + (r.version ? ' · v' + esc(r.version) : '') + ' · ' + new Date(r.date).toDateString();
      sections += tag('blockquote', 'style="margin:6px 0;padding:8px 12px;background:#faf4f4;border-left:3px solid #c0392b"',
        tag('span', 'style="color:#c0392b"', stars(r.rating)) + ' ' + esc(trunc(r.text, 220))
        + LT + 'br' + GT + tag('small', 'style="color:#777"', meta));
    }
  }
}

const total = recentAll.length;
const allAvg = total ? (recentAll.reduce((a, r) => a + r.rating, 0) / total).toFixed(2) : '—';
const summary = unavailable.length === STORES.length
  ? 'Neither store could be read this week'
  : total + ' new review' + (total === 1 ? '' : 's') + (total ? ' · overall average ' + allAvg + '★' : '') + (unavailable.length ? ' · ' + unavailable.join(', ') + ' unavailable' : '');
const subject = '📱 App reviews: ' + (unavailable.length === STORES.length ? 'stores unavailable this week'
  : total + ' new this week' + (total ? ' (avg ' + allAvg + '★)' : '') + (unavailable.length ? ', ' + unavailable.join(', ') + ' unavailable' : ''));
const html = tag('div', 'style="font-family:system-ui,Arial,sans-serif;max-width:620px"',
  tag('h2', 'style="margin:0 0 4px"', 'Weekly app review digest')
  + tag('p', 'style="color:#555;margin:0 0 12px"', esc(summary))
  + sections
  + LT + 'hr style="border:none;border-top:1px solid #eee;margin:20px 0 8px"' + GT
  + tag('p', 'style="color:#999;font-size:12px"', 'Sent by your n8n review-digest workflow.'));

return [{ json: { html, subject, totalRecent: total, overallAvg: allAvg, unavailable } }];
